inline ushort packHalf2ToUShort(half2 v) {
    v = saturate(v);
    v = round(v*255);
    ushort2 uv = ushort2(v);
    ushort res = (uv.x & 0x00ff) | ((uv.y & 0x00ff) << 8);
    return res;
}

inline half2 unpackHalf2FromUShort(ushort v) {
    half2 res;
    
    res.x = half(v & 0x00ff);
    res.y = half( (v & 0xff00) >> 8);
    
    return res/255.;
}
